<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
$sponsorId=(int)($user['id']??0);
$hasAccess=sponsor_table_exists($conn,'sponsor_programme_access');
$hasThreads=sponsor_table_exists($conn,'sponsor_communication_threads');
$hasMessages=sponsor_table_exists($conn,'sponsor_communication_messages');
$programmes=[];
if($hasAccess){$st=$conn->prepare("SELECT p.id,p.name FROM sponsor_programme_access a JOIN programmes p ON p.id=a.programme_id WHERE a.sponsor_user_id=? AND a.access_status='active' ORDER BY p.name");if($st){$st->bind_param('i',$sponsorId);$st->execute();$rs=$st->get_result();$programmes=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}}
$allowed=array_map(static fn($p)=>(int)$p['id'],$programmes);
$selected=(int)($_GET['thread']??$_POST['thread_id']??0);
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $postedToken=(string)($_POST['csrf_token']??'');$sessionToken=(string)($_SESSION['csrf_token']??$_SESSION['_csrf_token']??'');
 if($sessionToken!=='' && !hash_equals($sessionToken,$postedToken)){$error='Your session token has expired. Refresh the page and try again.';}
 elseif(!$hasThreads||!$hasMessages){$error='Communication tables are not installed. Import the supplied migration first.';}
 else{
  $action=(string)($_POST['action']??'');$subject=trim((string)($_POST['subject']??''));$body=trim((string)($_POST['message']??''));
  if($action==='new'){
   $pid=(int)($_POST['programme_id']??0);$type=(string)($_POST['enquiry_type']??'general');$validTypes=['general','progress_update','funding','beneficiary_outcomes','documentation','meeting_request','other'];
   if(!in_array($pid,$allowed,true))$error='Select a programme assigned to your sponsor account.';
   elseif(strlen($subject)<4||strlen($subject)>180)$error='Subject must be between 4 and 180 characters.';
   elseif(strlen($body)<10||strlen($body)>10000)$error='Message must be between 10 and 10,000 characters.';
   elseif(!in_array($type,$validTypes,true))$error='Select a valid enquiry type.';
   else{$st=$conn->prepare("INSERT INTO sponsor_communication_threads (sponsor_user_id,programme_id,subject,enquiry_type,status,priority,last_message_at,created_at,updated_at) VALUES (?,?,?,?,'open','normal',NOW(),NOW(),NOW())");if($st){$st->bind_param('iiss',$sponsorId,$pid,$subject,$type);if($st->execute()){$tid=(int)$st->insert_id;$st->close();$st=$conn->prepare("INSERT INTO sponsor_communication_messages (thread_id,sender_user_id,sender_role,message_body,created_at) VALUES (?,?,'sponsor',?,NOW())");if($st){$st->bind_param('iis',$tid,$sponsorId,$body);$st->execute();$st->close();$selected=$tid;$success='Your enquiry has been submitted.';}else $error='Could not save your message.';}else{$error='Could not create the enquiry.';$st->close();}}}
  }elseif($action==='reply'){
   $tid=(int)($_POST['thread_id']??0);if(strlen($body)<2||strlen($body)>10000)$error='Reply must be between 2 and 10,000 characters.';
   else{$st=$conn->prepare("SELECT id,status FROM sponsor_communication_threads WHERE id=? AND sponsor_user_id=? LIMIT 1");if($st){$st->bind_param('ii',$tid,$sponsorId);$st->execute();$thread=$st->get_result()->fetch_assoc();$st->close();if(!$thread)$error='Enquiry not found.';elseif($thread['status']==='closed')$error='This enquiry is closed. Reopen it before replying.';else{$st=$conn->prepare("INSERT INTO sponsor_communication_messages (thread_id,sender_user_id,sender_role,message_body,created_at) VALUES (?,?,'sponsor',?,NOW())");if($st){$st->bind_param('iis',$tid,$sponsorId,$body);if($st->execute()){$st->close();$st=$conn->prepare("UPDATE sponsor_communication_threads SET status='awaiting_response',last_message_at=NOW(),updated_at=NOW() WHERE id=? AND sponsor_user_id=?");$st->bind_param('ii',$tid,$sponsorId);$st->execute();$st->close();$selected=$tid;$success='Your follow-up has been sent.';}else{$error='Could not send your reply.';$st->close();}}}}}
  }elseif($action==='reopen'){$tid=(int)($_POST['thread_id']??0);$st=$conn->prepare("UPDATE sponsor_communication_threads SET status='open',updated_at=NOW() WHERE id=? AND sponsor_user_id=? AND status='closed'");if($st){$st->bind_param('ii',$tid,$sponsorId);$st->execute();$success=$st->affected_rows?'Enquiry reopened.':'Unable to reopen this enquiry.';$st->close();$selected=$tid;}}
 }
}
$threads=[];$messages=[];$activeThread=null;
if($hasThreads&&$hasMessages){$st=$conn->prepare("SELECT t.*,p.name programme_name,(SELECT COUNT(*) FROM sponsor_communication_messages m WHERE m.thread_id=t.id) message_count,(SELECT m.sender_role FROM sponsor_communication_messages m WHERE m.thread_id=t.id ORDER BY m.id DESC LIMIT 1) last_sender FROM sponsor_communication_threads t JOIN programmes p ON p.id=t.programme_id JOIN sponsor_programme_access a ON a.programme_id=t.programme_id AND a.sponsor_user_id=t.sponsor_user_id AND a.access_status='active' WHERE t.sponsor_user_id=? ORDER BY t.last_message_at DESC,t.id DESC");if($st){$st->bind_param('i',$sponsorId);$st->execute();$rs=$st->get_result();$threads=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}
 if($selected){$st=$conn->prepare("SELECT t.*,p.name programme_name FROM sponsor_communication_threads t JOIN programmes p ON p.id=t.programme_id WHERE t.id=? AND t.sponsor_user_id=? LIMIT 1");if($st){$st->bind_param('ii',$selected,$sponsorId);$st->execute();$activeThread=$st->get_result()->fetch_assoc();$st->close();}if($activeThread){$st=$conn->prepare("SELECT message_body,sender_role,created_at FROM sponsor_communication_messages WHERE thread_id=? ORDER BY id ASC");$st->bind_param('i',$selected);$st->execute();$rs=$st->get_result();$messages=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}}
}
sponsor_header('Sponsor communications','communications','Contact programme management, request updates and follow every interaction in one place.');
?>
<style>
.sc-layout{display:grid;grid-template-columns:minmax(260px,.78fr) minmax(0,1.5fr);gap:16px}.sc-card{background:var(--surface);border:1px solid var(--line);border-radius:16px;overflow:hidden;min-width:0}.sc-head{padding:16px 18px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px}.sc-head h2{font-size:15px;margin:0}.sc-body{padding:17px}.sc-thread{display:block;padding:13px 14px;border-bottom:1px solid var(--line);text-decoration:none;color:var(--text)}.sc-thread:hover,.sc-thread.active{background:var(--surface2)}.sc-thread strong{display:block;font-size:13px}.sc-thread small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.sc-pill{display:inline-flex;padding:3px 8px;border-radius:20px;background:var(--surface2);color:var(--muted);font-size:10px;font-weight:700}.sc-form{display:grid;gap:12px}.sc-form label{font-size:12px;font-weight:700;color:var(--text)}.sc-form input,.sc-form select,.sc-form textarea{width:100%;margin-top:5px;padding:11px 12px;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--text);font:inherit}.sc-form textarea{min-height:115px;resize:vertical}.sc-btn{border:0;border-radius:10px;padding:11px 15px;background:var(--primary);color:white;font-weight:700;cursor:pointer}.sc-alert{padding:12px 14px;border-radius:10px;margin-bottom:14px;background:var(--surface2);border:1px solid var(--line);font-size:12px}.sc-message{padding:13px 15px;border:1px solid var(--line);border-radius:13px;margin-bottom:12px;background:var(--surface2);max-width:88%}.sc-message.sponsor{margin-left:auto;background:color-mix(in srgb,var(--primary) 10%,var(--surface));}.sc-message p{white-space:pre-wrap;margin:7px 0 0;overflow-wrap:anywhere}.sc-message small{color:var(--muted);font-size:10px}.sc-empty{padding:28px 16px;text-align:center;color:var(--muted);font-size:12px}.sc-toolbar{display:flex;gap:9px;align-items:center;flex-wrap:wrap}@media(max-width:850px){.sc-layout{grid-template-columns:1fr}.sc-thread-list{max-height:340px;overflow:auto}.sc-message{max-width:96%}}
</style>
<?php if($error): ?><div class="sc-alert"><?= sponsor_e($error) ?></div><?php endif; ?><?php if($success): ?><div class="sc-alert"><?= sponsor_e($success) ?></div><?php endif; ?>
<?php if(!$hasAccess||!$hasThreads||!$hasMessages): ?><section class="sc-card"><div class="sc-body"><strong>Setup required</strong><p>Import <code>database/sponsor_communication_engagement_migration.sql</code> and ensure your sponsor account has assigned programme access.</p></div></section>
<?php elseif(!$programmes): ?><section class="sc-card"><div class="sc-empty">No programmes are assigned to your sponsor account yet. Contact the platform administrator to request access.</div></section>
<?php else: ?>
<div class="sc-toolbar" style="margin-bottom:14px"><span class="sc-pill"><?= count($threads) ?> enquiries</span><button class="sc-btn" type="button" onclick="document.getElementById('scNew').hidden=!document.getElementById('scNew').hidden">＋ New enquiry</button></div>
<section class="sc-card" id="scNew" hidden style="margin-bottom:16px"><div class="sc-head"><h2>Submit an enquiry</h2></div><div class="sc-body"><form class="sc-form" method="post"><input type="hidden" name="csrf_token" value="<?= sponsor_e($_SESSION['csrf_token']??$_SESSION['_csrf_token']??'') ?>"><input type="hidden" name="action" value="new"><label>Programme<select name="programme_id" required><option value="">Choose assigned programme</option><?php foreach($programmes as $p): ?><option value="<?= (int)$p['id'] ?>"><?= sponsor_e($p['name']) ?></option><?php endforeach; ?></select></label><label>Enquiry type<select name="enquiry_type"><option value="general">General enquiry</option><option value="progress_update">Progress update request</option><option value="funding">Funding / contribution</option><option value="beneficiary_outcomes">Beneficiary outcomes</option><option value="documentation">Reports or documentation</option><option value="meeting_request">Meeting request</option><option value="other">Other</option></select></label><label>Subject<input name="subject" maxlength="180" required minlength="4" placeholder="Briefly describe your enquiry"></label><label>Message<textarea name="message" required minlength="10" maxlength="10000" placeholder="Provide details or specify the update you need..."></textarea></label><div><button class="sc-btn" type="submit">Submit enquiry</button></div></form></div></section>
<div class="sc-layout"><section class="sc-card"><div class="sc-head"><h2>Interaction history</h2></div><div class="sc-thread-list"><?php if(!$threads): ?><div class="sc-empty">No enquiries yet. Use “New enquiry” to contact programme management.</div><?php else: foreach($threads as $t): ?><a class="sc-thread <?= $selected===(int)$t['id']?'active':'' ?>" href="<?= url('sponsor/communications.php?thread='.(int)$t['id']) ?>"><strong><?= sponsor_e($t['subject']) ?></strong><small><?= sponsor_e($t['programme_name']) ?> · <?= sponsor_date($t['last_message_at']) ?></small><small><span class="sc-pill"><?= sponsor_e(sponsor_status($t['status'])) ?></span> · <?= (int)$t['message_count'] ?> messages<?php if($t['last_sender']==='management'): ?> · Response received<?php endif; ?></small></a><?php endforeach; endif; ?></div></section>
<section class="sc-card"><div class="sc-head"><div><h2><?= $activeThread?sponsor_e($activeThread['subject']):'Conversation' ?></h2><?php if($activeThread): ?><small style="color:var(--muted)"><?= sponsor_e($activeThread['programme_name']) ?> · <?= sponsor_e(sponsor_status($activeThread['status'])) ?></small><?php endif; ?></div><?php if($activeThread&&$activeThread['status']==='closed'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= sponsor_e($_SESSION['csrf_token']??$_SESSION['_csrf_token']??'') ?>"><input type="hidden" name="action" value="reopen"><input type="hidden" name="thread_id" value="<?= $selected ?>"><button class="sc-btn">Reopen</button></form><?php endif; ?></div><div class="sc-body"><?php if(!$activeThread): ?><div class="sc-empty">Select an enquiry to view its complete conversation and send follow-ups.</div><?php else: ?><?php foreach($messages as $m): ?><article class="sc-message <?= $m['sender_role']==='sponsor'?'sponsor':'' ?>"><small><?= $m['sender_role']==='sponsor'?'You':'Programme management' ?> · <?= sponsor_date($m['created_at']) ?> <?= date('H:i',strtotime($m['created_at'])) ?></small><p><?= sponsor_e($m['message_body']) ?></p></article><?php endforeach; ?><?php if($activeThread['status']!=='closed'): ?><form class="sc-form" method="post" style="margin-top:18px"><input type="hidden" name="csrf_token" value="<?= sponsor_e($_SESSION['csrf_token']??$_SESSION['_csrf_token']??'') ?>"><input type="hidden" name="action" value="reply"><input type="hidden" name="thread_id" value="<?= $selected ?>"><label>Send a follow-up<textarea name="message" required minlength="2" maxlength="10000" placeholder="Add a question or request a follow-up..."></textarea></label><div><button class="sc-btn" type="submit">Send message</button></div></form><?php else: ?><div class="sc-alert">This enquiry is closed. Reopen it if you need to continue the conversation.</div><?php endif; ?><?php endif; ?></div></section></div><?php endif; ?>
<?php sponsor_footer(); ?>
